package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"
)

type PartRec struct { // 01 PART-REC, 15 bytes
	LbPart   string // PIC X(8) @0 len=8
	LbRegion string // PIC X(3) @8 len=3
	LbSerial int64  // PIC 9(4) @11 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsLabel string          // PIC X(20) len=20 = SPACES
var WsACount int64 = 0      // PIC 99 len=2 = 0
var WsTotalA int64 = 0      // PIC 999 len=3 = 0
var WsCount int64 = 0       // PIC 999 len=3 = 0

var PartRecData PartRec
var inputLines []string
var inputIdx int

func init() {
	WsLabel = strings.Repeat(" ", 20)
}

func delimitedBySpace(s string) string {
	if idx := strings.IndexByte(s, ' '); idx >= 0 {
		return s[:idx]
	}
	return s
}

func openInputPartFile() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to open input.dat: %v\n", err)
		os.Exit(1)
	}
	s := string(data)
	s = strings.ReplaceAll(s, "\r\n", "\n")
	s = strings.ReplaceAll(s, "\r", "\n")
	if s == "" {
		inputLines = []string{}
		inputIdx = 0
		return
	}
	raw := strings.Split(s, "\n")
	if strings.HasSuffix(s, "\n") {
		raw = raw[:len(raw)-1]
	}
	inputLines = raw
	inputIdx = 0
}

func closePartFile() {}

// paragraphs
func ReadPara() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	PartRecData.LbPart = line[0:8]
	PartRecData.LbRegion = line[8:11]
	serialStr := line[11:15]
	trimmed := strings.TrimSpace(serialStr)
	var v int64
	if trimmed != "" {
		if parsed, err := strconv.ParseInt(trimmed, 10, 64); err == nil {
			v = parsed
		} else {
			v = 0
		}
	} else {
		v = 0
	}
	v = v % 10000
	if v < 0 {
		v = -v
	}
	PartRecData.LbSerial = v
}

func ProcessPara() {
	WsLabel = strings.Repeat(" ", 20)
	WsACount = 0
	cnt := strings.Count(PartRecData.LbPart, "A")
	WsACount = (WsACount + int64(cnt)) % 100

	// STRING ... INTO WS-LABEL
	labelBytes := []byte(WsLabel) // 20 spaces
	pos := 0
	add := func(src string) {
		for i := 0; i < len(src); i++ {
			if pos < 20 {
				labelBytes[pos] = src[i]
				pos++
			} else {
				break
			}
		}
	}
	regionSrc := delimitedBySpace(PartRecData.LbRegion)
	add(regionSrc)
	add("-")
	partSrc := delimitedBySpace(PartRecData.LbPart)
	add(partSrc)
	add("-")
	serialSrc := fmt.Sprintf("%04d", PartRecData.LbSerial)
	add(serialSrc)
	WsLabel = string(labelBytes)

	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")

	WsTotalA = (WsTotalA + WsACount) % 1000
	WsCount = (WsCount + 1) % 1000

	countStr := fmt.Sprintf("%02d", WsACount)
	fmt.Printf("%s%s%s\n", WsLabel, " A=", countStr)

	ReadPara()
}

func SummaryPara() {
	fmt.Printf("LABELS: %03d A-TOTAL: %03d\n", WsCount, WsTotalA)
}

func MainPara() {
	openInputPartFile()
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	closePartFile()
	SummaryPara()
}

func main() {
	MainPara()
}
